//! Benchmarks for the performance building blocks.
//!
//! Each group pits a Vulcan primitive against the naive alternative it replaces, so a regression
//! shows up as a shrinking gap. Run locally with `cargo bench`; CI runs them under CodSpeed,
//! which counts instructions instead of measuring wall time, so results are stable enough to gate
//! pull requests.

// `criterion_group!` and `criterion_main!` expand to undocumented items that read env vars.
#![allow(missing_docs, clippy::disallowed_methods, reason = "code generated by criterion macros")]

use criterion::{BenchmarkId, Criterion, criterion_group, criterion_main};
use std::{collections::BTreeMap, hint::black_box};
use vulcan::{
    arena::{Bump, BumpExt},
    bytes::{Cursor, is_id_continue, is_whitespace},
    intern::Interner,
    sync::par_try_map,
};

/// A synthetic source mixing identifiers, whitespace and block comments.
fn source(words: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(words * 16);
    for i in 0..words {
        out.extend_from_slice(format!("ident_{} ", i % 97).as_bytes());
        if i % 8 == 0 {
            out.extend_from_slice(b"/* a comment that spans some bytes */ ");
        }
    }
    out
}

fn bench_scan(c: &mut Criterion) {
    let src = source(4096);
    let mut group = c.benchmark_group("scan");
    group.bench_function("cursor_table", |b| {
        b.iter(|| {
            let mut cursor = Cursor::new(black_box(&src));
            let mut idents = 0_usize;
            while !cursor.is_eof() {
                cursor.eat_while(is_whitespace);
                if cursor.eat_str(b"/*") {
                    cursor.skip_past(b"*/");
                } else if !cursor.eat_while(is_id_continue).is_empty() {
                    idents += 1;
                } else {
                    cursor.bump();
                }
            }
            idents
        });
    });
    group.bench_function("char_naive", |b| {
        b.iter(|| {
            let text = std::str::from_utf8(black_box(&src)).map_or("", |text| text);
            text.split_whitespace()
                .filter(|w| w.chars().all(|c| c.is_alphanumeric() || c == '_'))
                .count()
        });
    });
    group.finish();
}

fn bench_intern(c: &mut Criterion) {
    let words: Vec<String> = (0..10_000).map(|i| format!("ident_{}", i % 512)).collect();
    let mut group = c.benchmark_group("intern");
    group.bench_function("interner", |b| {
        b.iter(|| {
            let mut interner = Interner::with_capacity(512);
            for word in &words {
                black_box(interner.intern(word));
            }
            interner.len()
        });
    });
    group.bench_function("btreemap_string", |b| {
        b.iter(|| {
            let mut map = BTreeMap::new();
            for word in &words {
                let next = map.len();
                black_box(*map.entry(word.clone()).or_insert(next));
            }
            map.len()
        });
    });
    group.finish();
}

fn bench_alloc(c: &mut Criterion) {
    let mut group = c.benchmark_group("alloc_nodes");
    for count in [1_000_usize, 10_000] {
        group.bench_with_input(BenchmarkId::new("bump", count), &count, |b, &n| {
            b.iter(|| {
                let arena = Bump::new();
                let total: usize = (0..n).map(|i| arena.alloc_exact([i as u32; 4]).len()).sum();
                total
            });
        });
        group.bench_with_input(BenchmarkId::new("box", count), &count, |b, &n| {
            b.iter(|| {
                let nodes: Vec<Box<[u32]>> =
                    (0..n).map(|i| vec![i as u32; 4].into_boxed_slice()).collect();
                nodes.len()
            });
        });
    }
    group.finish();
}

fn bench_par(c: &mut Criterion) {
    let items: Vec<u64> = (0..256).collect();
    let work = |n: u64| Ok::<_, ()>((0..2_000_u64).fold(n, |acc, x| acc.wrapping_mul(31) ^ x));
    let mut group = c.benchmark_group("par_try_map");
    for enabled in [false, true] {
        group.bench_function(if enabled { "parallel" } else { "serial" }, |b| {
            b.iter(|| par_try_map(enabled, black_box(items.clone()), work));
        });
    }
    group.finish();
}

criterion_group!(benches, bench_scan, bench_intern, bench_alloc, bench_par);
criterion_main!(benches);
